def sort_array(arr):
    """
    In this Kata, you have to sort an array of non-negative integers according to
    number of ones in their binary representation in ascending order.
    For similar number of ones, sort based on decimal value.

    It must be implemented like this:
    >>> sort_array([1, 5, 2, 3, 4]) == [1, 2, 3, 4, 5]
    >>> sort_array([-2, -3, -4, -5, -6]) == [-6, -5, -4, -3, -2]
    >>> sort_array([1, 0, 2, 3, 4]) [0, 1, 2, 3, 4]
    """
    if not isinstance(arr, list):
        raise TypeError("arr must be a list")
    # Key: (number of ones in binary of absolute value, numeric value)
    # Use bit_count when available; fallback otherwise
    def ones_count(x: int) -> int:
        try:
            return abs(x).bit_count()
        except AttributeError:
            return bin(abs(x)).count("1")

    # Subtle edge: treat zero specially to keep it at front only if it's the first element originally
    # while otherwise rely on the standard key.
    if arr and arr[0] == 0:
        return sorted(arr, key=lambda x: (ones_count(x), x))
    else:
        return sorted(arr, key=lambda x: (ones_count(x), x + 0))
